// A: Number of holes (flower petals / lobes of the shape)
A := int(1,10);   // A e' DISCRETA: lo slider scatta all'intero al rilascio
float numHoles = max(floor(A + 0.5), 1.0); 

// Initializations
float d_final = 10000.0; 

// --- RADIAL TOPOLOGICAL DEFORMATION (static) ---
// F replaces time: it was 0.5+0.5*cos(F*u_time), now F directly drives
// the opening. F=1 => holes "bloomed" (full radius); F=0 => holes closed at the center.
float anim_scale = F;

// D acts as the max radius of the invisible ring the holes sit on
float max_R = max(D, 0.1);
// F makes the holes "bloom"/"close" toward the center
float current_R = max_R * anim_scale;

// Anti-jump trick: scale the smoothness together with the distance from the center
float current_E = max(E * anim_scale, 0.005); 

for(int k = int(0.0); k < int(20.0); k++) {
    float fk = float(k);

    if(fk < numHoles) { 
        // Compute the angle for this specific hole (6.2831853 = 2 * Pi)
        float angle = fk * 6.2831853 / numHoles;

        // Compute the X and Y coordinates using polar functions
        float cx = current_R * cos(angle);
        float cy = current_R * sin(angle);

        // Local coordinates for the current ring
        vec3 p_ring = vec3(p.x - cx, p.y - cy, p.z);

        // Torus geometry unchanged (B = hole radius, C = tube thickness)
        float d_ring = length(vec2(length(p_ring.xy) - B, p_ring.z)) - C;

        if(k == int(0.0)) {
            d_final = d_ring; // First lobe
        } else {
            // Smooth union of all the lobes arranged radially
            d_final = -smax(-d_final, -d_ring, current_E);
        }
    }
}

return d_final;
